    /// <summary>Convertit un tracé SVG (commandes M L H V C S Q T A Z) en GraphicsPath, mis à l'échelle de 24 à <paramref name="size"/>.</summary>
    public static GraphicsPath ToPath(string d, float size, float margin)
    {
        var path = new GraphicsPath(FillMode.Winding);
        var scale = (size - 2 * margin) / 24f;
        PointF P(float x, float y) => new(margin + x * scale, margin + y * scale);

        var t = new Tokens(d);
        float cx = 0, cy = 0, sx = 0, sy = 0, lcx = 0, lcy = 0; // point courant, début de figure, dernier point de contrôle
        char cmd = ' ', prev = ' ';
        bool open = false;
        while (t.More())
        {
            if (t.IsCommand()) cmd = t.Command();
            else if (cmd == ' ') break;
            bool rel = char.IsLower(cmd);
            float ox = rel ? cx : 0, oy = rel ? cy : 0;
            switch (char.ToUpperInvariant(cmd))
            {
                case 'M':
                    if (open) path.CloseFigure();
                    path.StartFigure(); open = true;
                    cx = ox + t.Num(); cy = oy + t.Num(); sx = cx; sy = cy;
                    cmd = rel ? 'l' : 'L'; // les points suivants sont des lignes
                    lcx = cx; lcy = cy; prev = 'M';
                    continue;
                case 'L':
                {
                    float x = ox + t.Num(), y = oy + t.Num();
                    path.AddLine(P(cx, cy), P(x, y)); cx = x; cy = y; break;
                }
                case 'H':
                {
                    float x = ox + t.Num();
                    path.AddLine(P(cx, cy), P(x, cy)); cx = x; break;
                }
                case 'V':
                {
                    float y = oy + t.Num();
                    path.AddLine(P(cx, cy), P(cx, y)); cy = y; break;
                }
                case 'C':
                {
                    float x1 = ox + t.Num(), y1 = oy + t.Num(), x2 = ox + t.Num(), y2 = oy + t.Num(), x = ox + t.Num(), y = oy + t.Num();
                    path.AddBezier(P(cx, cy), P(x1, y1), P(x2, y2), P(x, y));
                    lcx = x2; lcy = y2; cx = x; cy = y; prev = 'C'; continue;
                }
                case 'S':
                {
                    float x1 = prev == 'C' ? 2 * cx - lcx : cx, y1 = prev == 'C' ? 2 * cy - lcy : cy;
                    float x2 = ox + t.Num(), y2 = oy + t.Num(), x = ox + t.Num(), y = oy + t.Num();
                    path.AddBezier(P(cx, cy), P(x1, y1), P(x2, y2), P(x, y));
                    lcx = x2; lcy = y2; cx = x; cy = y; prev = 'C'; continue;
                }
                case 'Q':
                {
                    float qx = ox + t.Num(), qy = oy + t.Num(), x = ox + t.Num(), y = oy + t.Num();
                    AddQuad(path, P, cx, cy, qx, qy, x, y);
                    lcx = qx; lcy = qy; cx = x; cy = y; prev = 'Q'; continue;
                }
                case 'T':
                {
                    float qx = prev == 'Q' ? 2 * cx - lcx : cx, qy = prev == 'Q' ? 2 * cy - lcy : cy;
                    float x = ox + t.Num(), y = oy + t.Num();
                    AddQuad(path, P, cx, cy, qx, qy, x, y);
                    lcx = qx; lcy = qy; cx = x; cy = y; prev = 'Q'; continue;
                }
                case 'A':
                {
                    float rx = t.Num(), ry = t.Num(), rot = t.Num();
                    bool large = t.Flag(), sweep = t.Flag();
                    float x = ox + t.Num(), y = oy + t.Num();
                    AddArc(path, P, cx, cy, rx, ry, rot, large, sweep, x, y);
                    cx = x; cy = y; break;
                }
                case 'Z':
                    path.CloseFigure(); open = false;
                    cx = sx; cy = sy; prev = 'Z';
                    cmd = ' ';
                    continue;
                default:
                    return path;
            }
            prev = char.ToUpperInvariant(cmd);
        }
        return path;
    }

    private static void AddQuad(GraphicsPath path, Func<float, float, PointF> P, float x0, float y0, float qx, float qy, float x, float y)
    {
        path.AddBezier(P(x0, y0), P(x0 + 2f / 3 * (qx - x0), y0 + 2f / 3 * (qy - y0)), P(x + 2f / 3 * (qx - x), y + 2f / 3 * (qy - y)), P(x, y));
    }

    /// <summary>Arc elliptique SVG découpé en courbes de Bézier (méthode de la spécification SVG, annexe F.6).</summary>
    private static void AddArc(GraphicsPath path, Func<float, float, PointF> P, float x1, float y1, float rx, float ry, float rotDeg, bool large, bool sweep, float x2, float y2)
    {
        if (rx == 0 || ry == 0 || (x1 == x2 && y1 == y2)) { path.AddLine(P(x1, y1), P(x2, y2)); return; }
        double phi = rotDeg * Math.PI / 180, cos = Math.Cos(phi), sin = Math.Sin(phi);
        double dx = (x1 - x2) / 2.0, dy = (y1 - y2) / 2.0;
        double x1p = cos * dx + sin * dy, y1p = -sin * dx + cos * dy;
        double arx = Math.Abs(rx), ary = Math.Abs(ry);
        double lambda = x1p * x1p / (arx * arx) + y1p * y1p / (ary * ary);
        if (lambda > 1) { var s = Math.Sqrt(lambda); arx *= s; ary *= s; }
        double num = arx * arx * ary * ary - arx * arx * y1p * y1p - ary * ary * x1p * x1p;
        double den = arx * arx * y1p * y1p + ary * ary * x1p * x1p;
        double coef = Math.Sqrt(Math.Max(0, num / den)) * (large == sweep ? -1 : 1);
        double cxp = coef * arx * y1p / ary, cyp = -coef * ary * x1p / arx;
        double ccx = cos * cxp - sin * cyp + (x1 + x2) / 2.0, ccy = sin * cxp + cos * cyp + (y1 + y2) / 2.0;
        double Angle(double ux, double uy, double vx, double vy)
        {
            var a = Math.Atan2(ux * vy - uy * vx, ux * vx + uy * vy);
            return a;
        }
        double t1 = Angle(1, 0, (x1p - cxp) / arx, (y1p - cyp) / ary);
        double dt = Angle((x1p - cxp) / arx, (y1p - cyp) / ary, (-x1p - cxp) / arx, (-y1p - cyp) / ary);
        if (!sweep && dt > 0) dt -= 2 * Math.PI;
        else if (sweep && dt < 0) dt += 2 * Math.PI;
        int segs = (int)Math.Ceiling(Math.Abs(dt) / (Math.PI / 2));
        double step = dt / segs, k = 4.0 / 3 * Math.Tan(step / 4);
        PointF Pt(double ang, double dxk, double dyk)
        {
            double ex = arx * (Math.Cos(ang) + dxk), ey = ary * (Math.Sin(ang) + dyk);
            return P((float)(cos * ex - sin * ey + ccx), (float)(sin * ex + cos * ey + ccy));
        }
        for (int i = 0; i < segs; i++)
        {
            double a1 = t1 + i * step, a2 = a1 + step;
            path.AddBezier(Pt(a1, 0, 0), Pt(a1, -k * Math.Sin(a1), k * Math.Cos(a1)), Pt(a2, k * Math.Sin(a2), -k * Math.Cos(a2)), Pt(a2, 0, 0));
        }
    }

    /// <summary>Lecture des nombres d'un tracé SVG, y compris la forme compacte (« 1.5.5 », « -1-2 », drapeaux « 01 »).</summary>
    private sealed class Tokens
    {
        private readonly string _s;
        private int _i;
        public Tokens(string s) { _s = s; }

        private void Skip() { while (_i < _s.Length && (char.IsWhiteSpace(_s[_i]) || _s[_i] == ',')) _i++; }
        public bool More() { Skip(); return _i < _s.Length; }
        public bool IsCommand() { Skip(); return _i < _s.Length && char.IsLetter(_s[_i]) && _s[_i] is not ('e' or 'E'); }
        public char Command() { Skip(); return _s[_i++]; }

        public bool Flag()
        {
            Skip();
            if (_i >= _s.Length) throw new FormatException("tracé incomplet");
            return _s[_i++] == '1';
        }

        public float Num()
        {
            Skip();
            int start = _i;
            if (_i < _s.Length && (_s[_i] is '-' or '+')) _i++;
            bool dot = false, exp = false;
            while (_i < _s.Length)
            {
                var c = _s[_i];
                if (char.IsDigit(c)) { _i++; continue; }
                if (c == '.' && !dot && !exp) { dot = true; _i++; continue; }
                if ((c is 'e' or 'E') && !exp) { exp = true; _i++; if (_i < _s.Length && (_s[_i] is '-' or '+')) _i++; continue; }
                break;
            }
            if (_i == start) throw new FormatException("nombre attendu dans le tracé");
            return float.Parse(_s.AsSpan(start, _i - start), NumberStyles.Float, CultureInfo.InvariantCulture);
        }
    }
}
